entries[175972] = { ["name"] = "Animaversetztes Toxin", ["text"] = "Questgegenstand\nEinzigartig (8)\n\"Dieses ätzende Toxin wirkt stark zersetzend und ist außerdem mit Anima erfüllt. Diese Eigenschaften machen es zu einem potenten Reagenz für Zauber und Tränke.\"" }
